{"path":"tests/steps/status-badge-tone.steps.tsx","content":"import assert from 'node:assert/strict';

import { Given, Then, When } from '@cucumber/cucumber';
import type { IWorld } from '@cucumber/cucumber';
import { renderToStaticMarkup } from 'react-dom/server';

import { StatusBadge } from '../../status-badge.js';
import type { StatusBadgeProps } from '../../status-badge.js';

type Tone = NonNullable<StatusBadgeProps['tone']>;

interface BadgeScenarioState {
  readonly input: StatusBadgeProps;
  markup?: string;
}

const scenarioStates = new WeakMap<IWorld, BadgeScenarioState>();
const tones: readonly Tone[] = ['neutral', 'positive', 'warning', 'critical'];

function isTone(value: string): value is Tone {
  return tones.some((tone) => tone === value);
}

function scenarioState(world: IWorld): BadgeScenarioState {
  const state = scenarioStates.get(world);
  assert.ok(state, 'A badge must be given before it is rendered');
  return state;
}

function renderedMarkup(world: IWorld): string {
  const markup = scenarioState(world).markup;
  assert.ok(markup, 'The badge must be rendered before its markup is checked');
  return markup;
}

Given(
  'a badge for a passed review with the tone {string}',
  function (this: IWorld, tone: string) {
    assert.ok(isTone(tone), `Unsupported badge tone: ${tone}`);
    scenarioStates.set(this, { input: { status: 'passed', tone } });
  },
);

Given('a badge for a failed review with no tone', function (this: IWorld) {
  scenarioStates.set(this, { input: { status: 'failed' } });
});

When('the badge is rendered', function (this: IWorld) {
  const state = scenarioState(this);
  state.markup = renderToStaticMarkup(<StatusBadge {...state.input} />);
});

Then('its markup carries the tone {string}', function (this: IWorld, tone: string) {
  assert.ok(
    renderedMarkup(this).includes(`data-tone="${tone}"`),
    `Expected rendered badge markup to carry tone ${tone}`,
  );
});

Then('it still reads {string}', function (this: IWorld, label: string) {
  assert.ok(
    renderedMarkup(this).endsWith(`>${label}</span>`),
    `Expected rendered badge to read ${label}`,
  );
});
"}
